            ["XIDCONTINUE"] = "XIDCONTINUE",
            ["XIDS"] = "XIDSTART",
            ["XIDSTART"] = "XIDSTART",
            ["XPEO"] = "OLDPERSIAN",
            ["XSUX"] = "CUNEIFORM",
            ["YEZI"] = "YEZIDI",
