            ["ZZZZ"] = "UNKNOWN",
        }.ToFrozenDictionary(StringComparer.Ordinal);

    private static bool TryResolveEncodedRanges(string normalizedName, out string encoded)
    {
        if (EncodedRanges.TryGetValue(normalizedName, out encoded!) ||
            AdditionalEncodedRanges.TryGetValue(normalizedName, out encoded!))
        {
            return true;
        }

        return PropertyAliases.TryGetValue(normalizedName, out var canonical) &&
            (EncodedRanges.TryGetValue(canonical, out encoded!) ||
             AdditionalEncodedRanges.TryGetValue(canonical, out encoded!));
    }
}
